{
  "id": "da9e9b02-555f-4292-9e73-1e2a2e991851",
  "version": "1.8",
  "name": "BellevueWeatherFlow",
  "nodes": [
    {
      "id": "start",
      "type": "core.trigger.manual",
      "typeVersion": "1.0",
      "display": {
        "label": "Manual trigger"
      },
      "inputs": {
        "entryPointId": "b1aef1e7-0cbe-4caf-9aa7-488507a35191",
        "isDefaultEntryPoint": true
      }
    },
    {
      "id": "getBellevueWeather1",
      "type": "uipath.connector.custom-codereval-openmeteoapis.getcurrentweather",
      "typeVersion": "1.0.0",
      "display": {
        "label": "Get Bellevue Weather"
      },
      "inputs": {}
    },
    {
      "id": "evaluateWeather1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Evaluate: Nice Day?"
      },
      "inputs": {
        "script": "const weather = $vars.getBellevueWeather1.output;\nconst temperature = weather.current_weather.temperature;\nconst weatherCode = weather.current_weather.weathercode;\nconst precipitation = (weather.daily && weather.daily.precipitation_sum && weather.daily.precipitation_sum[0]) || 0;\n// Nice day = clear/partly cloudy (WMO code 0-2), at least 15 C, less than 1 mm rain\nconst isNiceDay = weatherCode <= 2 && temperature >= 15 && precipitation < 1;\nreturn {\n  temperature,\n  weatherCode,\n  precipitation,\n  isNiceDay,\n  verdict: isNiceDay\n    ? `It IS a nice day in Bellevue, WA! Temp: ${temperature}C, sky is clear (WMO code ${weatherCode}), only ${precipitation}mm of rain. Get outside!`\n    : `It is NOT a nice day in Bellevue, WA. Temp: ${temperature}C, WMO code: ${weatherCode}, precipitation: ${precipitation}mm. Stay cozy indoors!`\n};"
      }
    },
    {
      "id": "checkNiceDay1",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Is it a nice day?"
      },
      "inputs": {
        "expression": "$vars.evaluateWeather1.output.isNiceDay === true",
        "trueLabel": "Nice day",
        "falseLabel": "Not nice"
      }
    },
    {
      "id": "endNice1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Nice day in Bellevue!"
      },
      "inputs": {}
    },
    {
      "id": "endNotNice1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {
        "label": "Not a nice day"
      },
      "inputs": {}
    }
  ],
  "edges": [
    {
      "id": "e1",
      "source": "start",
      "sourceHandle": "output",
      "target": "getBellevueWeather1",
      "targetHandle": "input"
    },
    {
      "id": "e2",
      "source": "getBellevueWeather1",
      "sourceHandle": "output",
      "target": "evaluateWeather1",
      "targetHandle": "input"
    },
    {
      "id": "e3",
      "source": "evaluateWeather1",
      "sourceHandle": "success",
      "target": "checkNiceDay1",
      "targetHandle": "input"
    },
    {
      "id": "e4",
      "source": "checkNiceDay1",
      "sourceHandle": "true",
      "target": "endNice1",
      "targetHandle": "input"
    },
    {
      "id": "e5",
