parameters.old_string:
        "script": "const weather = $vars.getBellevueWeather1.output;
const temperature = weather.current_weather.temperature;
const weatherCode = weather.current_weather.weathercode;
const precipitation = (weather.daily && weather.daily.precipitation_sum && weather.daily.precipitation_sum[0]) || 0;
// Nice day = clear/partly cloudy (WMO code 0-2), at least 15 C, less than 1 mm rain
const isNiceDay = weatherCode <= 2 && temperature >= 15 && precipitation < 1;
return {
  temperature,
  weatherCode,
  precipitation,
  isNiceDay,
  verdict: isNiceDay
    ? `It IS a nice day in Bellevue, WA! Temp: ${temperature}C, sky is clear (WMO code ${weatherCode}), only ${precipitation}mm of rain. Get outside!`
    : `It is NOT a nice day in Bellevue, WA. Temp: ${temperature}C, WMO code: ${weatherCode}, precipitation: ${precipitation}mm. Stay cozy indoors!`
};"

